## Submitted testbench
```systemverilog
module tb;

  // -----------------------------------------------------------------
  // Parameters and signals
  // -----------------------------------------------------------------
  localparam int CLK_PERIOD = 8; // 125 MHz
  logic clk = 1'b0;
  logic rst = 1'b0;
  logic rxd = 1'b1;
  logic [15:0] prescale_val = 16'd1;
  logic [7:0] m_axis_tdata;
  logic m_axis_tvalid;
  logic m_axis_tready;
  logic [7:0] txd;
  logic [7:0] rx_busy;
  logic [7:0] s_axis_tdata = 8'd0;
  logic        s_axis_tvalid = 1'b0;
  logic        s_axis_tready_dummy;
  wire       m_axis_tready_wire;
  assign m_axis_tready_wire = 1'b1; // always ready for AXI output
  wire tx_busy_dummy;
  wire rx_overrun_error_dummy;
  wire rx_frame_error_dummy;

  // -----------------------------------------------------------------
  // DUT instantiation
  // -----------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready_dummy),
    .txd          (txd),
    .tx_busy      (tx_busy_dummy),
    .rx_busy      (rx_busy),
    .rx_overrun_error(rx_overrun_error_dummy),
    .rx_frame_error(rx_frame_error_dummy),
    .prescale     (prescale_val),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready_wire)
  );

  // -----------------------------------------------------------------
  // Helper tasks
  // -----------------------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic uart_send_byte(input byte unsigned b);
    int unsigned bit_clks = prescale_val * 8;
    // start bit
    rxd = 1'b0;
    wait_clks(bit_clks);
    // data bits, LSB first
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_clks(bit_clks);
    end
    // stop bit
    rxd = 1'b1;
    wait_clks(bit_clks);
    // idle (high)
    rxd = 1'b1;
  endtask

  task automatic do_reset();
    rst = 1'b1;
    wait_clks(2);
    rst = 1'b0;
    wait_clks(2);
    rst = 1'b0;
    wait_clks(2);
  endtask

  task automatic send_and_capture(input byte unsigned data);
    // Wait until receiver is idle
    while (rx_busy) @(negedge clk);
    // Transmit the byte on rxd
    uart_send_byte(data);
    // Give the DUT some time to present the word on m_axis_tvalid
    repeat (50) @(negedge clk);
  endtask

  // -----------------------------------------------------------------
  // Main stimulus
  // -----------------------------------------------------------------
  initial begin
    // Clock generation
    forever #(CLK_PERIOD/2) clk = ~clk;

    // Reset the design
    do_reset();

    // -------------------------------------------------------------
    // 1) Capture a frame at prescale = 1  (expected data 0xA5)
    // -------------------------------------------------------------
    @(negedge clk);
    prescale_val = 16'd1;                 // ensure prescale is 1
    send_and_capture(8'hA5);               // send 0xA5

    // -------------------------------------------------------------
    // 2) Change prescale to 2 while the receiver is idle,
    //    then capture a second frame with data 0x5A
    // -------------------------------------------------------------
    while (rx_busy) @(negedge clk);      // wait for idle
    @(negedge clk);
    prescale_val = 16'd2;                 // switch prescale
    repeat (4) @(negedge clk);           // small idle delay

    send_and_capture(8'h5A);               // transmit 0x5A

    // -------------------------------------------------------------
    // 3) End of simulation
    // -------------------------------------------------------------
    $finish;
  end

endmodule
```

